def comb_sort(nums):
    n = len(nums)
    gap = n
    shrink_factor = 1.3
    sorted_list = nums.copy()

    while gap != 1:
        gap = max(1, int(gap / shrink_factor))

        for i in range(n - gap):
            if sorted_list[i] > sorted_list[i + gap]:
                sorted_list[i], sorted_list[i + gap] = sorted_list[i + gap], sorted_list[i]

    return sorted_list
```

