def count_binary_seq(n):
    if n == 0:
        return 1

    # The number of valid sequences is given by the central binomial coefficient C(2n, n)
    # This can be computed as the product of (4*i - 2)/(i+1) for i from 1 to n
    result = 1
    for i in range(1, n + 1):
        result *= (4 * i - 2) / (i + 1)

    # Round to handle floating point precision issues
    return round(result)
